const fs = require('fs');
const path = require('path');

const jsonStr = fs.readFileSync('D:/gitclub/frontend/src/raw_profile.json', 'utf8');
const data = JSON.parse(jsonStr);

let rawHtml = data.content;

// The content looks like:
// <USER_REQUEST>\n<!DOCTYPE html> ... </html>..this is the code for profile page...

const match = rawHtml.match(/<!DOCTYPE html>[\s\S]*?<\/html>/);
if (match) {
  let html = match[0];

  // Apply our fixes:

  // 1. FAB buttons update (from our previous fix_fab.js)
  const fabRegex = /<div class="fixed bottom-6 right-6 z-50 flex items-center gap-space-xs p-1\.5 rounded-full bg-surface-container-highest\/90 backdrop-blur-xl shadow-\[0_12px_32px_-4px_rgba\(0,0,0,0\.65\)\]">[\s\S]*?<\/div>/;

  const newFab = `<div class="fixed bottom-6 right-6 z-50 flex items-center gap-space-xs p-1.5 rounded-full bg-surface-container-highest/90 backdrop-blur-xl shadow-[0_12px_32px_-4px_rgba(0,0,0,0.65)]">
    <a href="#" data-path="events" class="flex items-center gap-1.5 px-space-sm py-space-xs rounded-full bg-primary-container text-on-primary-container font-title-md text-body-sm hover:brightness-110 transition-all cursor-pointer">
      <span class="material-symbols-outlined text-[18px]">add</span><span>Event</span>
    </a>
    <a href="#" data-path="members" class="flex items-center gap-1.5 px-space-sm py-space-xs rounded-full bg-surface-container-high text-on-surface font-title-md text-body-sm hover:bg-surface-bright transition-all cursor-pointer">
      <span class="material-symbols-outlined text-[18px]">person_add</span><span>Member</span>
    </a>
    <a href="#" data-path="projects" class="flex items-center gap-1.5 px-space-sm py-space-xs rounded-full bg-surface-container-high text-on-surface font-title-md text-body-sm hover:bg-surface-bright transition-all cursor-pointer">
      <span class="material-symbols-outlined text-[18px]">create_new_folder</span><span>Project</span>
    </a>
    <a href="#" data-path="announcements" class="flex items-center gap-1.5 px-space-sm py-space-xs rounded-full bg-surface-container-high text-on-surface font-title-md text-body-sm hover:bg-surface-bright transition-all cursor-pointer">
      <span class="material-symbols-outlined text-[18px]">campaign</span><span>Broadcast</span>
    </a>
  </div>`;
  html = html.replace(fabRegex, newFab);

  // 2. Add id="theme-toggle" to dark mode button
  const btnRegex = /<button class="p-2 rounded-lg text-on-surface-variant hover:text-on-surface hover:bg-surface-container transition-colors" title="Theme toggle">/g;
  const newBtn = '<button id="theme-toggle" class="p-2 rounded-lg text-on-surface-variant hover:text-on-surface hover:bg-surface-container transition-colors" title="Theme toggle">';
  html = html.replace(btnRegex, newBtn);

  // 3. Remove inline tailwind CDN block since we are compiling it locally
  const twCdnRegex = /<script src="https:\/\/cdn\.tailwindcss\.com"><\/script><script id="tailwind-config">[\s\S]*?<\/script>/;
  html = html.replace(twCdnRegex, '');

  fs.writeFileSync('D:/gitclub/frontend/src/settings.html', html);
  console.log('Saved settings.html');
} else {
  console.log('Could not parse html');
}
